-- =====================================================================
-- Umoja SACCO practice dataset (fictional)
-- PostgreSQL. Creates schema "sacco" with 7 tables.
-- Safe to run more than once: it drops and recreates only this schema.
-- Data runs up to 30 September 2026.
-- =====================================================================

DROP SCHEMA IF EXISTS sacco CASCADE;
CREATE SCHEMA sacco;
SET search_path TO sacco;

-- ---------------------------------------------------------------------
-- branches (manager_id is linked to staff after staff is loaded)
-- ---------------------------------------------------------------------
CREATE TABLE branches (
    branch_id    INT PRIMARY KEY,
    branch_name  VARCHAR(50) NOT NULL UNIQUE,
    town         VARCHAR(50) NOT NULL,
    opened_date  DATE NOT NULL,
    manager_id   INT
);



-- ---------------------------------------------------------------------
-- staff (manager_id points to another staff member)
-- ---------------------------------------------------------------------
CREATE TABLE staff (
    staff_id    INT PRIMARY KEY,
    first_name  VARCHAR(50) NOT NULL,
    last_name   VARCHAR(50) NOT NULL,
    role        VARCHAR(40) NOT NULL,
    branch_id   INT REFERENCES branches(branch_id),
    manager_id  INT REFERENCES staff(staff_id),
    hire_date   DATE NOT NULL,
    salary      NUMERIC(10, 2) NOT NULL,
    email       VARCHAR(100) NOT NULL UNIQUE
);



UPDATE branches SET manager_id = 4 WHERE branch_id = 1;
UPDATE branches SET manager_id = 10 WHERE branch_id = 2;
UPDATE branches SET manager_id = 15 WHERE branch_id = 3;
UPDATE branches SET manager_id = 20 WHERE branch_id = 4;
UPDATE branches SET manager_id = 25 WHERE branch_id = 5;
UPDATE branches SET manager_id = 30 WHERE branch_id = 6;
UPDATE branches SET manager_id = 35 WHERE branch_id = 7;
UPDATE branches SET manager_id = 40 WHERE branch_id = 8;

ALTER TABLE branches
    ADD CONSTRAINT fk_branch_manager FOREIGN KEY (manager_id) REFERENCES staff(staff_id);

-- ---------------------------------------------------------------------
-- members (referred_by points to another member)
-- ---------------------------------------------------------------------
CREATE TABLE members (
    member_id      INT PRIMARY KEY,
    first_name     VARCHAR(50) NOT NULL,
    last_name      VARCHAR(50) NOT NULL,
    gender         CHAR(1) NOT NULL CHECK (gender IN ('M', 'F')),
    date_of_birth  DATE NOT NULL,
    phone          VARCHAR(10) NOT NULL UNIQUE,
    email          VARCHAR(100) NOT NULL UNIQUE,
    branch_id      INT NOT NULL REFERENCES branches(branch_id),
    join_date      DATE NOT NULL,
    referred_by    INT REFERENCES members(member_id)
);




