-- ---------------------------------------------------------------------
-- loan_products
-- ---------------------------------------------------------------------
CREATE TABLE loan_products (
    product_id            INT PRIMARY KEY,
    product_name          VARCHAR(50) NOT NULL UNIQUE,
    annual_interest_rate  NUMERIC(5, 2) NOT NULL,
    max_term_months       INT NOT NULL
);



-- ---------------------------------------------------------------------
-- loans
--   status: Pending (approved, not yet paid out), Active, Closed (fully repaid), Defaulted
--   disbursed_date is NULL for Pending loans
-- ---------------------------------------------------------------------
CREATE TABLE loans (
    loan_id         INT PRIMARY KEY,
    member_id       INT NOT NULL REFERENCES members(member_id),
    product_id      INT NOT NULL REFERENCES loan_products(product_id),
    officer_id      INT NOT NULL REFERENCES staff(staff_id),
    principal       NUMERIC(12, 2) NOT NULL,
    interest_rate   NUMERIC(5, 2) NOT NULL,
    term_months     INT NOT NULL,
    applied_date    DATE NOT NULL,
    disbursed_date  DATE,
    status          VARCHAR(10) NOT NULL CHECK (status IN ('Pending', 'Active', 'Closed', 'Defaulted'))
);




-- ---------------------------------------------------------------------
-- repayments (one row per monthly instalment paid)
-- ---------------------------------------------------------------------
CREATE TABLE repayments (
    repayment_id  INT PRIMARY KEY,
    loan_id       INT NOT NULL REFERENCES loans(loan_id),
    payment_date  DATE NOT NULL,
    amount        NUMERIC(12, 2) NOT NULL CHECK (amount > 0),
    channel       VARCHAR(20) NOT NULL CHECK (channel IN ('M-Pesa', 'Bank Transfer', 'Cash'))
);
















-- ---------------------------------------------------------------------
-- savings_transactions
-- ---------------------------------------------------------------------
CREATE TABLE savings_transactions (
    txn_id     INT PRIMARY KEY,
    member_id  INT NOT NULL REFERENCES members(member_id),
    txn_date   DATE NOT NULL,
    txn_type   VARCHAR(10) NOT NULL CHECK (txn_type IN ('Deposit', 'Withdrawal')),
    amount     NUMERIC(12, 2) NOT NULL CHECK (amount > 0)
);

































-- ---------------------------------------------------------------------
-- Quick check: row counts
-- ---------------------------------------------------------------------
SELECT 'branches' AS table_name, COUNT(*) AS row_count FROM branches
UNION ALL SELECT 'staff', COUNT(*) FROM staff
UNION ALL SELECT 'members', COUNT(*) FROM members
UNION ALL SELECT 'loan_products', COUNT(*) FROM loan_products
UNION ALL SELECT 'loans', COUNT(*) FROM loans
UNION ALL SELECT 'repayments', COUNT(*) FROM repayments
UNION ALL SELECT 'savings_transactions', COUNT(*) FROM savings_transactions;







